WITH with_windows AS (SELECT id, store_id, product_id, quantity, last_restock, NTILE(3) OVER w_recent quantity_bucket, ROW_NUMBER() OVER w_running event_seq, ROW_NUMBER() OVER w_running row_seq, AVG(quantity) OVER w_grp quantity_avg_2 FROM inventory WINDOW w_recent AS (ORDER BY quantity DESC, id), w_running AS (PARTITION BY store_id ORDER BY last_restock DESC, id), w_grp AS (PARTITION BY YEAR(last_restock), store_id ORDER BY quantity, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)) SELECT s.id, s.store_id, s.product_id, s.quantity_bucket, s.event_seq, s.row_seq, (SELECT MAX(i2.quantity) FROM inventory i2 WHERE i2.product_id = s.product_id) AS max_inventory_quantity FROM with_windows s ORDER BY quantity_bucket DESC
